<?php /** @var array $admins @var bool $required @var array $coverage @var array $posture @var bool $canManage @var int $currentUserId @var \Core\Security\Csrf $csrf @var string $basePath */ ?>
<?php $complete = $coverage['enabled'] > 0 && $coverage['protected'] === $coverage['enabled']; ?>
<section class="security-hero card"><div><p class="section-kicker">Access posture</p><h2><?= $complete ? 'Administrator access is protected.' : 'Some administrators still need MFA.' ?></h2><p><?= $complete ? 'Every active administrator has multi-factor authentication enabled.' : ($coverage['enabled'] - $coverage['protected']) . ' active account(s) can still sign in with a password alone.' ?></p></div><div class="security-score <?= $complete ? 'is-good' : '' ?>"><strong><?= $coverage['enabled'] ? (int) round($coverage['protected'] / $coverage['enabled'] * 100) : 100 ?>%</strong><span>MFA coverage</span></div></section>
<?php $currentAdmin = current(array_filter($admins, static fn (array $admin): bool => (int) $admin['id'] === $currentUserId)); if ($currentAdmin && !$currentAdmin['mfa_enabled'] && !$currentAdmin['disabled']): ?><section class="notice-row notice-warning mfa-action-notice"><div><h2>Protect your administrator account</h2><p>Multi-factor authentication is not configured for your account. Add an authenticator before enabling the site-wide requirement.</p></div><a class="btn small" href="<?= e_attr($basePath) ?>/admin/profile">Set up MFA</a></section><?php endif; ?>
<div class="metric-grid"><div class="metric"><span>Protected accounts</span><strong><?= (int) $coverage['protected'] ?>/<?= (int) $coverage['enabled'] ?></strong><small>active administrators using MFA</small></div><div class="metric"><span>Policy</span><strong class="<?= $required ? 'text-ok' : '' ?>"><?= $required ? 'Required' : 'Optional' ?></strong><small>administrator sign-in requirement</small></div><div class="metric"><span>Active sessions</span><strong><?= (int) $posture['sessions'] ?></strong><small>across enabled accounts</small></div><div class="metric"><span>Enabled owners</span><strong><?= (int) $posture['owners'] ?></strong><small>last-owner protection is active</small></div></div>

<section class="card"><div class="card-heading"><div><p class="section-kicker">Policy</p><h2>Administrator safeguards</h2><p class="card-subtitle">Requiring MFA redirects unprotected administrators to their profile until enrollment is complete.</p></div></div><?php if ($canManage): ?><form method="post" action="<?= e_attr($basePath) ?>/admin/security" data-confirm="<?= $required ? 'Make multi-factor authentication optional for administrators?' : 'Require multi-factor authentication for every administrator?' ?>"><?= $csrf->field() ?><input type="hidden" name="require_mfa" value="0"><label class="toggle-control"><span><strong>Require multi-factor authentication</strong><small>Your own account must already be protected before Core allows this policy.</small></span><input type="checkbox" name="require_mfa" value="1" <?= $required ? 'checked' : '' ?> data-auto-submit><span class="toggle-track" aria-hidden="true"></span></label></form><?php else: ?><p class="notice-row warn">You can review security posture, but changing the site policy requires Settings permission.</p><?php endif; ?></section>

<section class="card"><div class="card-heading"><div><p class="section-kicker">Account evidence</p><h2>Administrator security</h2><p class="card-subtitle">Session and recovery-code counts update as administrators sign in or secure their accounts.</p></div><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/users">Manage accounts</a></div><div class="security-account-grid"><?php foreach ($admins as $admin): ?><article class="security-account <?= $admin['disabled'] ? 'is-disabled' : '' ?>"><div class="account-identity"><span class="account-avatar" aria-hidden="true"><?= e(strtoupper(substr((string) $admin['username'], 0, 1))) ?></span><div><strong><?= e($admin['username']) ?></strong><small><?= e(ucfirst((string) $admin['role'])) ?><?= (int) $admin['id'] === $currentUserId ? ' · You' : '' ?></small></div></div><div class="security-account-state"><span class="badge <?= $admin['disabled'] ? 'bad' : 'ok' ?>"><?= $admin['disabled'] ? 'Disabled' : 'Active' ?></span><span class="badge <?= $admin['mfa_enabled'] ? 'ok' : 'warn' ?>"><?= $admin['mfa_enabled'] ? 'MFA enabled' : 'MFA not configured' ?></span></div><dl><div><dt>Sessions</dt><dd><?= (int) $admin['active_sessions'] ?></dd></div><div><dt>Recovery codes</dt><dd><?= (int) $admin['recovery_codes'] ?></dd></div><div><dt>Last sign-in</dt><dd><?= e($admin['last_login_at'] ?? 'Never') ?></dd></div></dl><?php if ((int) $admin['id'] === $currentUserId && !$admin['mfa_enabled'] && !$admin['disabled']): ?><a class="security-account-action" href="<?= e_attr($basePath) ?>/admin/profile">Set up MFA on your profile →</a><?php endif; ?></article><?php endforeach; ?></div></section>
